import{_ as e,o as r,c as n,a0 as o}from"./chunks/framework.DScjKhBS.js";const p=JSON.parse('{"title":"Secure SDLC and agent governance","description":"SSDLC agent pack, Cloud Buddy, data-engineering AI plan, and multi-agent curriculum.","frontmatter":{"title":"Secure SDLC and agent governance","description":"SSDLC agent pack, Cloud Buddy, data-engineering AI plan, and multi-agent curriculum."},"headers":[],"relativePath":"reports/edi-repos-analysis/04-secure-sdlc-governance.md","filePath":"reports/edi-repos-analysis/04-secure-sdlc-governance.md"}'),a={name:"reports/edi-repos-analysis/04-secure-sdlc-governance.md"};function d(s,t,i,c,l,g){return r(),n("div",null,[...t[0]||(t[0]=[o('<h1 id="secure-sdlc-and-agent-governance" tabindex="-1">Secure SDLC and agent governance <a class="header-anchor" href="#secure-sdlc-and-agent-governance" aria-label="Permalink to &quot;Secure SDLC and agent governance&quot;">​</a></h1><hr><h4 id="elixirr-secure-sdlc-agent-pack" tabindex="-1"><code>elixirr-secure-sdlc-agent-pack</code> <a class="header-anchor" href="#elixirr-secure-sdlc-agent-pack" aria-label="Permalink to &quot;`elixirr-secure-sdlc-agent-pack`&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Field</th><th>Detail</th></tr></thead><tbody><tr><td><strong>Purpose</strong></td><td>Codifies Elixirr Secure SDLC into Cursor rules, skills, and shared markdown guidance for agent-assisted delivery</td></tr><tr><td><strong>Tech stack</strong></td><td>Markdown (<code>.md</code>, <code>.mdc</code>), Cursor agent configuration — no application runtime</td></tr><tr><td><strong>Organization</strong></td><td><code>shared/</code> (16 SSDLC principle docs); <code>.cursor/rules/</code> (22 scoped rules); <code>.cursor/skills/</code> (20 review workflows)</td></tr><tr><td><strong>Coding style</strong></td><td>Policy-as-markdown; rules use globs for file-type scoping; traceability to SSDLC source enforced</td></tr><tr><td><strong>CI/testing</strong></td><td>N/A — content repo</td></tr><tr><td><strong>Advantages</strong></td><td>Comprehensive coverage (mobile, AI, data pipelines, IaC); explicit &quot;do not add policy without SSDLC backing&quot;</td></tr><tr><td><strong>Disadvantages</strong></td><td>No standalone commands yet; effectiveness depends on team adoption</td></tr><tr><td><strong>WP/PHP transfer</strong></td><td><code>03-secure-coding.mdc</code> explicitly includes <code>**/*.php</code> in globs — secure coding guidance applies directly. Import into WP plugin/theme repos.</td></tr></tbody></table><hr><h4 id="danske-bank-wp2-cloud-buddy-ai-agent" tabindex="-1"><code>danske-bank-wp2-cloud-buddy-ai-agent</code> <a class="header-anchor" href="#danske-bank-wp2-cloud-buddy-ai-agent" aria-label="Permalink to &quot;`danske-bank-wp2-cloud-buddy-ai-agent`&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Field</th><th>Detail</th></tr></thead><tbody><tr><td><strong>Purpose</strong></td><td>Danske Bank &quot;Cloud Buddy&quot; — enterprise AI agent platform for incident management, public cloud services, App2Cloud onboarding. Teams bot, RAG ingestion, Bedrock AgentCore</td></tr><tr><td><strong>Tech stack</strong></td><td>Python 3.11–3.12, LangGraph/Strands, AWS Bedrock AgentCore, MCP, boto3, Terraform, Microsoft Teams SDK, GitHub Actions, Docker/ECR</td></tr><tr><td><strong>Organization</strong></td><td><code>ai-agents/</code> (runtimes, workflows, MCP tools, ingestion, Terraform); <code>teams-integration/</code>; domain split by workstream</td></tr><tr><td><strong>Coding style</strong></td><td>Pydantic settings, structured logging, pytest with live AWS integration tests</td></tr><tr><td><strong>CI/testing</strong></td><td>Per-workflow GitHub Actions (Ruff, pytest, Docker build/push, deploy)</td></tr><tr><td><strong>Advantages</strong></td><td>Production-grade agent architecture; MCP tools vs workflows separation; extensive operational runbooks</td></tr><tr><td><strong>Disadvantages</strong></td><td>High complexity; fragmented CI; outdated Terraform; client-specific credentials. Note: &quot;wp2&quot; is project name, not WordPress</td></tr><tr><td><strong>WP/PHP transfer</strong></td><td>MCP tools ≈ REST endpoints with permission callbacks. SSM parameter registry ≈ WP options/transients. Agent orchestration ≈ plugin hook lifecycle.</td></tr></tbody></table><hr><h4 id="data-engineering-ai-plan" tabindex="-1"><code>data-engineering-ai-plan</code> <a class="header-anchor" href="#data-engineering-ai-plan" aria-label="Permalink to &quot;`data-engineering-ai-plan`&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Field</th><th>Detail</th></tr></thead><tbody><tr><td><strong>Purpose</strong></td><td>AI–human pipeline: meeting transcript → BRD → data model + tech spec → architecture. Deterministic Python ingest; LLM via Cursor Agent Skills</td></tr><tr><td><strong>Tech stack</strong></td><td>Python, Click CLI, Pydantic v2, PyYAML, python-docx, pytest (19 modules, fully offline)</td></tr><tr><td><strong>Organization</strong></td><td><code>src/</code> (CLI, normalizers); <code>.cursor/skills/</code> (5 generation skills); <code>outputs/</code> (versioned artefacts); <code>tests/</code></td></tr><tr><td><strong>Coding style</strong></td><td>Excellent docstrings; explicit maturity/version contracts; collision-safe batch naming; auditable artefact graph</td></tr><tr><td><strong>CI/testing</strong></td><td>No CI; pytest runs fully offline; refresh scripts for audit trails</td></tr><tr><td><strong>Advantages</strong></td><td>Best-in-set documentation; human-in-the-loop by design; deterministic ingest separated from non-deterministic generation</td></tr><tr><td><strong>Disadvantages</strong></td><td>Cursor-dependent for full value; Windows-centric setup docs</td></tr><tr><td><strong>WP/PHP transfer</strong></td><td>Tiered artefact graph ≈ content hierarchy. Version/maturity gates ≈ post status workflow. Normalizer CLI ≈ WP-CLI import commands.</td></tr></tbody></table><hr><h4 id="data-enigneering-ai-enablement" tabindex="-1"><code>data-enigneering-ai-enablement</code> <a class="header-anchor" href="#data-enigneering-ai-enablement" aria-label="Permalink to &quot;`data-enigneering-ai-enablement`&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Field</th><th>Detail</th></tr></thead><tbody><tr><td><strong>Purpose</strong></td><td>Planned shared AI enablement library for data engineering — rules, skills, templates, platform overlays</td></tr><tr><td><strong>Tech stack</strong></td><td>Markdown/YAML documentation scaffold only</td></tr><tr><td><strong>Organization</strong></td><td>README describes intended <code>core/</code>, <code>platforms/</code>, <code>tools/</code>, <code>governance/</code> — none present locally</td></tr><tr><td><strong>Advantages</strong></td><td>Sound core-first, platform-overlay architecture</td></tr><tr><td><strong>Disadvantages</strong></td><td>Local clone is README-only; name typo reduces discoverability</td></tr><tr><td><strong>WP/PHP transfer</strong></td><td>Same pattern as shared mu-plugin or Composer package of coding standards with per-client overlays.</td></tr></tbody></table><hr><h4 id="multi-agent-systems" tabindex="-1"><code>multi-agent-systems</code> <a class="header-anchor" href="#multi-agent-systems" aria-label="Permalink to &quot;`multi-agent-systems`&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Field</th><th>Detail</th></tr></thead><tbody><tr><td><strong>Purpose</strong></td><td>Internal Elixirr Digital course on production multi-agent LLM systems (Modules 0–10)</td></tr><tr><td><strong>Tech stack</strong></td><td>Markdown/Obsidian vault; LangGraph, Google ADK, Microsoft Agent Framework (documented)</td></tr><tr><td><strong>Organization</strong></td><td><code>Module N - Title/</code> folders; Obsidian wiki-links + Mermaid; Acme Corp worked example</td></tr><tr><td><strong>Coding style</strong></td><td>Documentation-first; no runnable sample apps</td></tr><tr><td><strong>CI/testing</strong></td><td>None; Module 8 covers agent testing patterns conceptually</td></tr><tr><td><strong>Advantages</strong></td><td>Comprehensive curriculum (observability, security, eval, deployment)</td></tr><tr><td><strong>Disadvantages</strong></td><td>No executable labs; LLM version references will age</td></tr><tr><td><strong>WP/PHP transfer</strong></td><td>Evaluation beyond pass/fail, guardrails, observability — applicable for WP AI plugins or content agents.</td></tr></tbody></table><hr>',17)])])}const h=e(a,[["render",d]]);export{p as __pageData,h as default};
